use vstd::prelude::*;

verus! {

pub struct Interval {
    pub min: i32,
    pub max: i32,
}

impl Interval {
    pub open spec fn valid(&self) -> bool {
        self.min < self.max
    }
}

pub struct ChebyshevPoly {
    pub coef: Vec<i32>,
    pub domain: Interval,
    pub window: Interval,
}

fn chebyshev(coef: Vec<i8>) -> (result: ChebyshevPoly)
    requires
        coef.len() > 0,
    ensures
        // coefficients converted to i32, same length/order
        result.coef.len() == coef.len(),
        forall|i: int| 0 <= i < coef.len() ==> result.coef[i] == coef[i] as i32,

        // default intervals [-1, 1]
        result.domain.min == -1,
        result.domain.max ==  1,
        result.window.min == -1,
        result.window.max ==  1,

        // validity
        result.domain.valid(),
        result.window.valid(),
{
    let mut out: Vec<i32> = Vec::new();
    let mut i: usize = 0;

    while i < coef.len()
        invariant
            0 <= i <= coef.len(),
            out.len() == i,
            forall|j: int| 0 <= j < i ==> out[j] == coef[j] as i32,
            coef.len() > 0,
        decreases
            coef.len() - i,
    {
        out.push(coef[i] as i32);
        i = i + 1;
    }

    let domain = Interval { min: -1, max: 1 };
    let window = Interval { min: -1, max: 1 };

    // Help the verifier discharge the .valid() postconditions
    assert(domain.valid());
    assert(window.valid());

    ChebyshevPoly { coef: out, domain, window }
}

} // verus!

